import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken(); int n = (int) st.nval;
        st.nextToken(); long k = (long) st.nval;
        if (k >= 3) { System.out.println(0); return; } // two equal appended diffs, then their difference is 0
        long[] a = new long[n];
        for (int i = 0; i < n; i++) { st.nextToken(); a[i] = (long) st.nval; }
        Arrays.sort(a);
        long ans = a[0];
        for (int i = 1; i < n; i++) ans = Math.min(ans, a[i] - a[i - 1]);
        if (k == 1 || ans == 0) { System.out.println(ans); return; }
        // k == 2: every first difference d, then its distance to the nearest original value.
        for (int i = 1; i < n; i++)
            for (int j = 0; j < i; j++) {
                long d = a[i] - a[j];
                int lo = 0, hi = n;
                while (lo < hi) { int mid = (lo + hi) >>> 1; if (a[mid] < d) lo = mid + 1; else hi = mid; }
                if (lo < n) ans = Math.min(ans, a[lo] - d);
                if (lo > 0) ans = Math.min(ans, d - a[lo - 1]);
                if (ans == 0) { System.out.println(0); return; }
            }
        System.out.println(ans);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"slices"
	"sort"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	var k int64
	fmt.Fscan(in, &n, &k)
	if k >= 3 { // two equal appended diffs, then their difference is 0
		fmt.Println(0)
		return
	}
	a := make([]int64, n)
	for i := range a {
		fmt.Fscan(in, &a[i])
	}
	slices.Sort(a)
	ans := a[0]
	for i := 1; i < n; i++ {
		ans = min(ans, a[i]-a[i-1])
	}
	if k == 1 || ans == 0 {
		fmt.Println(ans)
		return
	}
	// k == 2: every first difference d, then its distance to the nearest original value.
	for i := 1; i < n; i++ {
		for j := 0; j < i; j++ {
			d := a[i] - a[j]
			p := sort.Search(n, func(x int) bool { return a[x] >= d })
			if p < n {
				ans = min(ans, a[p]-d)
			}
			if p > 0 {
				ans = min(ans, d-a[p-1])
			}
			if ans == 0 {
				fmt.Println(0)
				return
			}
		}
	}
	fmt.Println(ans)
}
